cd /root && python3 - <<'PY'
import openpyxl, os, re
path='/root/output/result.xlsx'
wb = openpyxl.load_workbook(path, data_only=False)
ws = wb['Task']
print('exists', os.path.exists(path), 'size', os.path.getsize(path))
for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    print('===', rng, '===')
    for row in ws[rng]:
        print([(c.coordinate, c.value) for c in row])

bad=[]
for row in ws.iter_rows():
    for c in row:
        v=c.value
        if isinstance(v,str) and v.startswith('='):
            if '_xlfn.' in v or '.INC' in v or '.EXC' in v:
                bad.append((c.coordinate,v))
            if 'INDEX(' in v:
                if 'Data!$H$21:$L$38' not in v or 'Data!$D$21:$D$38' not in v or 'Data!$H$4:$L$4' not in v:
                    bad.append((c.coordinate,'bad index range '+v))
print('bad_formula_markers', bad)

# Verify exact formulas for calculated sections.
errors=[]
for offset, r in enumerate(range(35,41)):
    for ci in range(8,13):
        col=openpyxl.utils.get_column_letter(ci)
        expected=f'=({col}{12+offset}-{col}{19+offset})/{col}{26+offset}*100'
        if ws[f'{col}{r}'].value != expected:
            errors.append((f'{col}{r}',ws[f'{col}{r}'].value,expected))
for ci in range(8,13):
    col=openpyxl.utils.get_column_letter(ci)
    expected_stats={
        f'{col}42':f'=MIN({col}35:{col}40)',
        f'{col}43':f'=MAX({col}35:{col}40)',
        f'{col}44':f'=MEDIAN({col}35:{col}40)',
        f'{col}45':f'=AVERAGE({col}35:{col}40)',
        f'{col}46':f'=PERCENTILE({col}35:{col}40,0.25)',
        f'{col}47':f'=PERCENTILE({col}35:{col}40,0.75)',
        f'{col}50':f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for cell, expected in expected_stats.items():
        if ws[cell].value != expected:
            errors.append((cell,ws[cell].value,expected))
print('formula_errors', errors)
